const K8V = {H:1, B:3, C:4, N:5, O:6, F:7, P:5, S:6, Cl:7, Br:7, I:7};
const kS = (id, o) => molSVG(null, Object.assign({m:{a:KMOL[id].a, b:KMOL[id].b}, full:false, bl:30, title:'structure'}, o || {}));      // skeletal
const kD = (id, o) => molSVG(null, Object.assign({m:{a:KMOL[id].ha, b:KMOL[id].hb}, full:true, bl:34, title:'structure'}, o || {}));    // displayed (every H)
const kTxt = s => `<div class="kfx">${esc(s)}</div>`;
const kAng = (a, b) => { let x = Math.abs(a - b) % (2*Math.PI); return x > Math.PI ? 2*Math.PI - x : x; };
/* Lewis structure: every atom, every bond, lone pairs as dot pairs, formal charges. o: {lp:[per atom], b:[bonds], hl:[atoms], noq, bl} */
function kLewis(id, o){
  o = o || {}; const m = KMOL[id], A = m.ha, B = o.b || m.hb, bl = o.bl || 40, LP = o.lp || A.map(a => a[5]), hl = new Set(o.hl || []);
  const P = A.map(a => [a[1]*bl, a[2]*bl]), nb = A.map(() => []), f = v => v.toFixed(1);
  B.forEach(b => { nb[b[0]].push(b[1]); nb[b[1]].push(b[0]); });
  const R = s => s === 'H' ? 6.5 : 7.5 + (s.length - 1)*4;
  let x0 = 1e9, y0 = 1e9, x9 = -1e9, y9 = -1e9; const grow = (x, y, r) => { x0 = Math.min(x0, x - r); x9 = Math.max(x9, x + r); y0 = Math.min(y0, y - r); y9 = Math.max(y9, y + r); };
  let under = '', g = '';
  A.forEach((a, i) => { if (hl.has(i)) under += `<circle class="mhl" style="stroke-width:3" cx="${f(P[i][0])}" cy="${f(P[i][1])}" r="15"/>`; });
  B.forEach(b => { const [i, j, ord] = b, dx = P[j][0] - P[i][0], dy = P[j][1] - P[i][1], d = Math.hypot(dx, dy) || 1, ux = dx/d, uy = dy/d, nx = -uy, ny = ux;
    const c1 = R(A[i][0]) + 2, c2 = R(A[j][0]) + 2, offs = ord === 3 ? [-4.4, 0, 4.4] : ord === 2 ? [-2.8, 2.8] : [0];
    offs.forEach(k => { g += `<line class="mb" x1="${f(P[i][0] + ux*c1 + nx*k)}" y1="${f(P[i][1] + uy*c1 + ny*k)}" x2="${f(P[j][0] - ux*c2 + nx*k)}" y2="${f(P[j][1] - uy*c2 + ny*k)}"/>`; }); });
  const CAND = [-Math.PI/2, 0, Math.PI/2, Math.PI, -Math.PI/4, Math.PI/4, 3*Math.PI/4, -3*Math.PI/4];
  A.forEach((a, i) => { const [x, y] = P[i], sym = a[0], q = a[3] || 0;
    const dirs = nb[i].map(j => Math.atan2(P[j][1] - y, P[j][0] - x)), used = [];
    for (let k = 0; k < (LP[i] || 0); k++){ let best = null, bs = -9;
      CAND.forEach((c, ci) => { if (used.indexOf(c) >= 0) return; const sc = Math.min(9, ...dirs.concat(used).map(d => kAng(d, c))) - (ci > 3 ? 0.12 : 0); if (sc > bs + 1e-6){ bs = sc; best = c; } });
      used.push(best); const r = R(sym) + 4.5, cx = x + Math.cos(best)*r, cy = y + Math.sin(best)*r, px = -Math.sin(best)*3.2, py = Math.cos(best)*3.2;
      g += `<circle class="lpd" cx="${f(cx + px)}" cy="${f(cy + py)}" r="1.9"/><circle class="lpd" cx="${f(cx - px)}" cy="${f(cy - py)}" r="1.9"/>`; grow(cx, cy, 5); }
    const cls = 'mt' + ({O:' el-o', N:' el-n', S:' el-s', P:' el-p', I:' el-i'}[sym] || '');
    g += `<text class="${cls}" x="${f(x)}" y="${f(y)}" font-size="16" text-anchor="middle" dominant-baseline="central">${sym}</text>`; grow(x, y, R(sym) + 2);
    if (q && !o.noq){ let best = -Math.PI/4, bs = -9;
      [-Math.PI/4, -3*Math.PI/4, Math.PI/4, 3*Math.PI/4, -Math.PI/2, 0].forEach(c => { const sc = Math.min(9, ...dirs.concat(used).map(d => kAng(d, c))); if (sc > bs + 1e-6){ bs = sc; best = c; } });
      const r = R(sym) + 11.5, qx = x + Math.cos(best)*r, qy = y + Math.sin(best)*r;
      g += `<text class="mq" x="${f(qx)}" y="${f(qy)}" font-size="12.5" text-anchor="middle" dominant-baseline="central">${(Math.abs(q) > 1 ? Math.abs(q) : '') + (q > 0 ? '+' : '−')}</text>`; grow(qx, qy, 7); } });
  const pad = 4, W = x9 - x0 + 2*pad, H = y9 - y0 + 2*pad;
  return `<svg class="molsvg lewis" viewBox="${f(x0 - pad)} ${f(y0 - pad)} ${f(W)} ${f(H)}" width="${Math.round(W)}" height="${Math.round(H)}" role="img" aria-label="Lewis structure">${under}${g}</svg>`;
}
